     * `upfront` is used for dimensions like purchasing a subscription, or seats for a plan. Where as `arrear` is used for dimensions like usage based billing. Dimensions can be comingled in an offering, so you can have a dimension that is billed `upfront` and another that is billed `arrear`.
     * Optional, if not included will be `arrear` by default.
     * @example "upfront"
     */
    @IsOptional()
    @IsEnum(PaymentSchedule, {
        message: (args: ValidationArguments) => {
            const { value, constraints } = args;
            const correctValues = Object.values(constraints[0]);
            return `paymentSchedule: The value ${value} is not a valid value for the sampleType field. The correct values are: ${correctValues}`;
        },
        each: true,
    })
    public paymentSchedule?: PaymentSchedule;

    /**
     * Time interval to aggregate dimension usage data for billing.
     * <br><br>
     * Default: `"hour"`
     */
    @ApiProperty({
        name: 'aggregationInterval',
        const {
            consumptionUnit,
            dimensionName,
            usageIncrement,
            rounding,
            usageEntitlement,
            overageAllowed,
            consumptionPrice,
            businessID,
            aggregationInterval: argumentAggregationInternal,
            aggregationMethod: argumentAggregationMethod,
            metadata,
            tiers,
            paymentSchedule,
            sampleType: createDimensionSampleType,
            tiersGroupByMetadata,
        } = createDimensionDto;
        let measurementId;

        //eslint-disable-next-line
        //@ts-ignore
        if (createDimensionDto?.measurementId === null) {
            measurementId = undefined;
        }
        //eslint-disable-next-line
        //@ts-ignore
        else if (createDimensionDto?.measurement?.measurementId) {
            //eslint-disable-next-line
            //@ts-ignore
            measurementId = createDimensionDto?.measurement?.measurementId;
        } else {
            //eslint-disable-next-line
            //@ts-ignore
            measurementId = createDimensionDto?.measurementId;
        }
        let sampleType;
        if (!createDimensionSampleType && paymentSchedule === PaymentSchedule.upfront) {
            sampleType = SampleType.continious;
        } else if (createDimensionSampleType) {
            sampleType = createDimensionSampleType;
        } else {
            sampleType = SampleType.gauge;
        }
        const input = {
            typeofDimension: 'numerical',
            numerical: {
                numericalType: numericalType['int'],
                dimensionUnit: consumptionUnit.unit,
                dimensionUnitType: consumptionUnit.type.toLowerCase(),
                aggregationInterval: argumentAggregationInternal
                    ? argumentAggregationInternal
                    : aggregationInterval['Hour'],
                aggregationMethod: argumentAggregationMethod ? argumentAggregationMethod : aggregationMethod['max'],
                priceSegments: [
                    {
                        lowerLimit: '0',
