            dimensionId,
            dimensionName,
            categorical: {},
            measurementId,
            metadata,
            paymentSchedule: paymentSchedule ? paymentSchedule : PaymentSchedule.arrear,
        };
        // eslint-disable-next-line @typescript-eslint/ban-ts-comment
        //@ts-ignore
        return input;
    }
}
