const { usageData } = SupportedResources;

/** What a dimension's aggregation method makes of a set of readings. */
const reduceSamples = (values: number[], method: aggregationMethod): number => {
    if (values.length === 0) {
        return 0;
    }
    switch (method) {
        case aggregationMethod.max:
            return Math.max(...values);
        case aggregationMethod.min:
            return Math.min(...values);
        case aggregationMethod.average:
            return values.reduce((total, value) => total + value, 0) / values.length;
        case aggregationMethod.count:
            return values.length;
        case aggregationMethod.last:
            return values[values.length - 1];
        default:
            return values.reduce((total, value) => total + value, 0);
    }
};

/** The stretch of time one step of a curve covers. */
type UsageStep = { start: Date; end: Date };

/** One row of a dimension's answer: a curve, and the group it belongs to. */
type UsageCurve = {
    metadataGroup?: Record<string, string>;
    usage: BasicUsageDocument[] | UsageResponseDocument[];
};

/** Steps are asked for in one of these sizes; anything else is read as an hour. */
const stepSizeOf = (interval: aggregationInterval): aggregationInterval =>
    interval === aggregationInterval.month || interval === aggregationInterval.day
        ? interval
        : aggregationInterval.hour;

/** Where the clock aligned step of the requested size holding an instant begins. */
const stepStartOf = (instant: Date, interval: aggregationInterval): Date => {
    switch (stepSizeOf(interval)) {
        case aggregationInterval.month:
            return new Date(Date.UTC(instant.getUTCFullYear(), instant.getUTCMonth(), 1));
        case aggregationInterval.day:
            return new Date(Date.UTC(instant.getUTCFullYear(), instant.getUTCMonth(), instant.getUTCDate()));
        default:
            return new Date(
                Date.UTC(instant.getUTCFullYear(), instant.getUTCMonth(), instant.getUTCDate(), instant.getUTCHours()),
            );
    }
};

/** Where the step following the one beginning at an edge begins. */
const stepAfter = (edge: Date, interval: aggregationInterval): Date => {
    switch (stepSizeOf(interval)) {
        case aggregationInterval.month:
            return new Date(Date.UTC(edge.getUTCFullYear(), edge.getUTCMonth() + 1, 1));
        case aggregationInterval.day:
            return new Date(Date.UTC(edge.getUTCFullYear(), edge.getUTCMonth(), edge.getUTCDate() + 1));
        default:
            return new Date(
                Date.UTC(edge.getUTCFullYear(), edge.getUTCMonth(), edge.getUTCDate(), edge.getUTCHours() + 1),
            );
    }
};

/**
 * The steps a window is answered in: edges sit on the clock at the requested
 * size, and the first and last step are cut back to the window itself so the
 * curve never reaches outside what was asked for.
 */
export const usageStepsOf = ({
    startTime,
    endTime,
    interval,
}: {
    startTime: string | Date;
    endTime: string | Date;
    interval: aggregationInterval;
}): UsageStep[] => {
    const windowStart = new Date(startTime);
    const windowEnd = new Date(endTime);
    if (!(windowEnd.getTime() > windowStart.getTime())) {
        return [];
    }
    const steps: UsageStep[] = [];
    let edge = stepStartOf(windowStart, interval);
    while (edge.getTime() < windowEnd.getTime()) {
        const next = stepAfter(edge, interval);
        steps.push({
            start: edge.getTime() < windowStart.getTime() ? windowStart : edge,
            end: next.getTime() > windowEnd.getTime() ? windowEnd : next,
        });
        edge = next;
    }
    return steps;
};

/** A dimension whose readings stand until the next one replaces them. */
const isProvisioned = ({ sampleType, paymentSchedule }: Partial<ReadDimensionResponseData>): boolean =>
    sampleType === SampleType.continious || (!sampleType && paymentSchedule === PaymentSchedule.upfront);

/** A dimension priced by the metadata groups its readings arrive with. */
const isMetadataPriced = ({ tiersGroupByMetadata }: Partial<ReadDimensionResponseData>): boolean =>
    Array.isArray(tiersGroupByMetadata) && tiersGroupByMetadata.length > 0;

/**
 * A set of readings laid out over steps: each step holds what its own readings
 * make of it, a step of a provisioned dimension with no reading of its own
 * holds the level standing over it, and any other empty step holds nothing.
 */
const curveOf = ({
    steps,
    samples,
    method,
    provisioned,
    standingLevel,
}: {
    steps: UsageStep[];
    samples: UsageSample[];
    method: aggregationMethod;
    provisioned: boolean;
    standingLevel?: number;
}): UsageResponseDocument[] => {
    const ordered = [...samples].sort(
        (one, other) => new Date(one.timestamp).getTime() - new Date(other.timestamp).getTime(),
    );
    let level = standingLevel;
    let next = 0;
    return steps.map(({ start, end }) => {
        while (next < ordered.length && new Date(ordered[next].timestamp).getTime() < start.getTime()) {
            level = ordered[next].value;
