import {
    aggregationInterval,
    aggregationMethod,
    PaymentSchedule,
    ReadDimensionResponseData,
    SampleType,
} from '../dimensions/dto/create-dimension.dto.js';
import { AggregatedUsageResponse, MetadataGroupedAggregatedUsageResponse } from '../customer/dto/read-customer.dto.js';
import { UsageAggregationEvent, usageStepsOf } from './usageAggregation.event.js';

/**
 * The readings these expectations rest on are the ones published to the usage
 * metric store for the sandbox business:
 *
 * dim_widgets     cus_sandbox01  00:15 -> 4, 00:45 -> 1, 00:50 -> 2, 00:55 -> 1,
 *                                02:02 -> 2, 02:05 -> 6, 02:10 -> 1, 02:35 -> 9
 * dim_widgets     cus_sandbox02  01:05 -> 500
 * dim_licences    cus_sandbox01  2024-01-30T12:00 -> 2, 01:15 -> 5
 * dim_egress_gb   cus_sandbox01  {environment: production} 00:45 -> 3, 02:05 -> 1
 *                                {environment: staging}    01:10 -> 9
 *
 * all on 2024-02-14 unless said otherwise.
 */
const businessID = 'demo-labs';
const customerId = 'cus_sandbox01';
const offeringId = 'off_sandbox';

const dimension = (fields: Partial<ReadDimensionResponseData>): ReadDimensionResponseData =>
    ({
        aggregationInterval: aggregationInterval.hour,
        aggregationMethod: aggregationMethod.sum,
        ...fields,
    } as ReadDimensionResponseData);

const usageFor = async ({
    dimensions,
    startTime,
    endTime,
    customer = customerId,
}: {
    dimensions: ReadDimensionResponseData[];
    startTime: string;
    endTime: string;
    customer?: string;
}) =>
    (await UsageAggregationEvent.getAggregateUsageForDimension({
        businessID,
        customerId: customer,
        clientID: customer,
        startTime,
        endTime,
        offeringDocument: { offeringId, dimensions },
    } as UsageAggregationEvent)) as (AggregatedUsageResponse | MetadataGroupedAggregatedUsageResponse)[];

const curveOf = (row: AggregatedUsageResponse) =>
    row.usage.map(({ startTime, endTime, value }) => [startTime, endTime, value]);

describe('usageStepsOf', () => {
    it('cuts the first and last step back to the window and leaves the edges on the clock', () => {
        expect(
            usageStepsOf({
                startTime: '2024-02-14T00:30:00.000Z',
                endTime: '2024-02-14T02:15:00.000Z',
                interval: aggregationInterval.hour,
            }).map(({ start, end }) => [start.toISOString(), end.toISOString()]),
        ).toEqual([
            ['2024-02-14T00:30:00.000Z', '2024-02-14T01:00:00.000Z'],
            ['2024-02-14T01:00:00.000Z', '2024-02-14T02:00:00.000Z'],
            ['2024-02-14T02:00:00.000Z', '2024-02-14T02:15:00.000Z'],
        ]);
    });

    it('steps a day at a time on midnight', () => {
        expect(
            usageStepsOf({
                startTime: '2024-02-13T12:00:00.000Z',
                endTime: '2024-02-15T00:00:00.000Z',
                interval: aggregationInterval.day,
            }).map(({ start, end }) => [start.toISOString(), end.toISOString()]),
        ).toEqual([
            ['2024-02-13T12:00:00.000Z', '2024-02-14T00:00:00.000Z'],
            ['2024-02-14T00:00:00.000Z', '2024-02-15T00:00:00.000Z'],
        ]);
    });

    it('steps a calendar month at a time on the first of the month', () => {
        expect(
            usageStepsOf({
                startTime: '2024-01-15T06:00:00.000Z',
                endTime: '2024-03-02T00:00:00.000Z',
                interval: aggregationInterval.month,
            }).map(({ start, end }) => [start.toISOString(), end.toISOString()]),
        ).toEqual([
            ['2024-01-15T06:00:00.000Z', '2024-02-01T00:00:00.000Z'],
            ['2024-02-01T00:00:00.000Z', '2024-03-01T00:00:00.000Z'],
            ['2024-03-01T00:00:00.000Z', '2024-03-02T00:00:00.000Z'],
        ]);
    });

    it('has nothing to say about an empty window', () => {
        expect(
            usageStepsOf({
                startTime: '2024-02-14T00:00:00.000Z',
                endTime: '2024-02-14T00:00:00.000Z',
                interval: aggregationInterval.hour,
            }),
        ).toEqual([]);
    });
});

describe('getAggregateUsageForDimension', () => {
    it('answers a metered dimension with a step for every step of the window', async () => {
        const [widgets] = await usageFor({
            dimensions: [dimension({ dimensionId: 'dim_widgets' })],
            startTime: '2024-02-14T00:30:00.000Z',
            endTime: '2024-02-14T03:15:00.000Z',
        });

        expect(widgets.dimensionId).toEqual('dim_widgets');
        expect(widgets.offeringId).toEqual(offeringId);
        expect(curveOf(widgets)).toEqual([
            ['2024-02-14T00:30:00.000Z', '2024-02-14T01:00:00.000Z', '4'],
            ['2024-02-14T01:00:00.000Z', '2024-02-14T02:00:00.000Z', '0'],
            ['2024-02-14T02:00:00.000Z', '2024-02-14T03:00:00.000Z', '18'],
            ['2024-02-14T03:00:00.000Z', '2024-02-14T03:15:00.000Z', '0'],
        ]);
    });

    it('keeps a reading landing on the start of the window and leaves out one on its end', async () => {
        const [widgets] = await usageFor({
            dimensions: [dimension({ dimensionId: 'dim_widgets' })],
            startTime: '2024-02-14T00:45:00.000Z',
            endTime: '2024-02-14T02:05:00.000Z',
        });

        expect(curveOf(widgets)).toEqual([
            ['2024-02-14T00:45:00.000Z', '2024-02-14T01:00:00.000Z', '4'],
            ['2024-02-14T01:00:00.000Z', '2024-02-14T02:00:00.000Z', '0'],
            ['2024-02-14T02:00:00.000Z', '2024-02-14T02:05:00.000Z', '2'],
        ]);
    });

    it('makes of each step whatever the dimension asks of its own readings', async () => {
        const [widgets] = await usageFor({
            dimensions: [dimension({ dimensionId: 'dim_widgets', aggregationMethod: aggregationMethod.max })],
            startTime: '2024-02-14T00:00:00.000Z',
            endTime: '2024-02-14T03:00:00.000Z',
        });

        expect(curveOf(widgets)).toEqual([
            ['2024-02-14T00:00:00.000Z', '2024-02-14T01:00:00.000Z', '4'],
            ['2024-02-14T01:00:00.000Z', '2024-02-14T02:00:00.000Z', '0'],
            ['2024-02-14T02:00:00.000Z', '2024-02-14T03:00:00.000Z', '9'],
        ]);
    });

    it('carries a provisioned dimension standing level through the steps that add nothing', async () => {
        const [licences] = await usageFor({
            dimensions: [
                dimension({
                    dimensionId: 'dim_licences',
                    aggregationMethod: aggregationMethod.last,
                    sampleType: SampleType.continious,
                }),
            ],
            startTime: '2024-02-14T00:30:00.000Z',
            endTime: '2024-02-14T03:15:00.000Z',
        });

        expect(curveOf(licences)).toEqual([
            ['2024-02-14T00:30:00.000Z', '2024-02-14T01:00:00.000Z', '2'],
            ['2024-02-14T01:00:00.000Z', '2024-02-14T02:00:00.000Z', '5'],
            ['2024-02-14T02:00:00.000Z', '2024-02-14T03:00:00.000Z', '5'],
            ['2024-02-14T03:00:00.000Z', '2024-02-14T03:15:00.000Z', '5'],
        ]);
    });

    it('reads a dimension billed upfront as provisioned as well', async () => {
        const [licences] = await usageFor({
            dimensions: [
                dimension({
                    dimensionId: 'dim_licences',
                    aggregationMethod: aggregationMethod.last,
                    paymentSchedule: PaymentSchedule.upfront,
                }),
            ],
            startTime: '2024-02-14T02:00:00.000Z',
            endTime: '2024-02-14T04:00:00.000Z',
        });

        expect(curveOf(licences)).toEqual([
            ['2024-02-14T02:00:00.000Z', '2024-02-14T03:00:00.000Z', '5'],
            ['2024-02-14T03:00:00.000Z', '2024-02-14T04:00:00.000Z', '5'],
        ]);
    });

    it('leaves a metered dimension step with no readings at nothing', async () => {
        const [widgets] = await usageFor({
            dimensions: [dimension({ dimensionId: 'dim_widgets' })],
            startTime: '2024-02-14T04:00:00.000Z',
            endTime: '2024-02-14T06:00:00.000Z',
        });

        expect(curveOf(widgets)).toEqual([
            ['2024-02-14T04:00:00.000Z', '2024-02-14T05:00:00.000Z', '0'],
            ['2024-02-14T05:00:00.000Z', '2024-02-14T06:00:00.000Z', '0'],
        ]);
    });

    it('still answers with every step for a customer holding no readings at all', async () => {
        const [nothing] = await usageFor({
            dimensions: [dimension({ dimensionId: 'dim_widgets' })],
            startTime: '2024-02-14T00:30:00.000Z',
            endTime: '2024-02-14T02:00:00.000Z',
            customer: 'cus_nobody',
        });

        expect(nothing.dimensionId).toEqual('dim_widgets');
        expect(curveOf(nothing)).toEqual([
            ['2024-02-14T00:30:00.000Z', '2024-02-14T01:00:00.000Z', '0'],
            ['2024-02-14T01:00:00.000Z', '2024-02-14T02:00:00.000Z', '0'],
        ]);
    });

    it('keeps one customer readings out of another curve', async () => {
        const [widgets] = await usageFor({
            dimensions: [dimension({ dimensionId: 'dim_widgets' })],
            startTime: '2024-02-14T01:00:00.000Z',
            endTime: '2024-02-14T02:00:00.000Z',
            customer: 'cus_sandbox02',
        });

        expect(curveOf(widgets)).toEqual([['2024-02-14T01:00:00.000Z', '2024-02-14T02:00:00.000Z', '500']]);
    });

    it('answers every published group of a metadata priced dimension on its own', async () => {
        const rows = (await usageFor({
            dimensions: [
                dimension({
                    dimensionId: 'dim_egress_gb',
                    tiersGroupByMetadata: [
                        { metadataGroups: { environment: 'production' }, tiers: [] },
                        { metadataGroups: { environment: 'staging' }, tiers: [] },
                    ],
                } as unknown as Partial<ReadDimensionResponseData>),
            ],
            startTime: '2024-02-14T00:30:00.000Z',
            endTime: '2024-02-14T03:00:00.000Z',
        })) as MetadataGroupedAggregatedUsageResponse[];

        expect(rows).toHaveLength(2);
        rows.forEach((row) => expect(row.dimensionId).toEqual('dim_egress_gb'));
        const production = rows.find(({ metadataGroup }) => metadataGroup?.environment === 'production');
        const staging = rows.find(({ metadataGroup }) => metadataGroup?.environment === 'staging');

        expect(curveOf(production)).toEqual([
            ['2024-02-14T00:30:00.000Z', '2024-02-14T01:00:00.000Z', '3'],
            ['2024-02-14T01:00:00.000Z', '2024-02-14T02:00:00.000Z', '0'],
            ['2024-02-14T02:00:00.000Z', '2024-02-14T03:00:00.000Z', '1'],
        ]);
        expect(curveOf(staging)).toEqual([
            ['2024-02-14T00:30:00.000Z', '2024-02-14T01:00:00.000Z', '0'],
            ['2024-02-14T01:00:00.000Z', '2024-02-14T02:00:00.000Z', '9'],
            ['2024-02-14T02:00:00.000Z', '2024-02-14T03:00:00.000Z', '0'],
        ]);
    });

    it('holds a dimension priced without metadata groups together across its published series', async () => {
        const rows = await usageFor({
            dimensions: [dimension({ dimensionId: 'dim_egress_gb' })],
            startTime: '2024-02-14T00:00:00.000Z',
            endTime: '2024-02-14T02:00:00.000Z',
        });

        expect(rows).toHaveLength(1);
        expect(curveOf(rows[0])).toEqual([
            ['2024-02-14T00:00:00.000Z', '2024-02-14T01:00:00.000Z', '3'],
            ['2024-02-14T01:00:00.000Z', '2024-02-14T02:00:00.000Z', '9'],
        ]);
    });

    it('answers a day at a time when a day is what is asked for', async () => {
        const [widgets] = await usageFor({
            dimensions: [dimension({ dimensionId: 'dim_widgets', aggregationInterval: aggregationInterval.day })],
            startTime: '2024-02-13T12:00:00.000Z',
            endTime: '2024-02-14T06:00:00.000Z',
        });

        expect(curveOf(widgets)).toEqual([
            ['2024-02-13T12:00:00.000Z', '2024-02-14T00:00:00.000Z', '0'],
            ['2024-02-14T00:00:00.000Z', '2024-02-14T06:00:00.000Z', '26'],
        ]);
    });

    it('answers a month at a time when a month is what is asked for', async () => {
        const [licences] = await usageFor({
            dimensions: [
                dimension({
                    dimensionId: 'dim_licences',
                    aggregationInterval: aggregationInterval.month,
                    aggregationMethod: aggregationMethod.last,
                    sampleType: SampleType.continious,
                }),
            ],
            startTime: '2024-01-01T00:00:00.000Z',
            endTime: '2024-03-01T00:00:00.000Z',
        });

        expect(curveOf(licences)).toEqual([
            ['2024-01-01T00:00:00.000Z', '2024-02-01T00:00:00.000Z', '2'],
            ['2024-02-01T00:00:00.000Z', '2024-03-01T00:00:00.000Z', '5'],
        ]);
    });

    it('hands back the readings themselves when no steps are asked for', async () => {
        const [widgets] = await usageFor({
            dimensions: [dimension({ dimensionId: 'dim_widgets', aggregationInterval: aggregationInterval.none })],
            startTime: '2024-02-14T00:00:00.000Z',
            endTime: '2024-02-14T01:00:00.000Z',
        });

        expect(widgets.usage).toHaveLength(4);
    });
});
