/**
 * How far back the standing level of a provisioned dimension is looked for,
 * one widening window at a time, so the common case of a recent reading stays
 * a small ask and a long standing level is still found.
 */
const STANDING_LEVEL_LOOKBACKS_IN_MS = [
    36e5, // an hour
    864e5, // a day
    6048e5, // a week
    2592e6, // thirty days
    7776e6, // ninety days
    31536e6, // a year
    94608e6, // three years
];

/**
 * The last reading a series holds before an instant, however long before it
 * was published. A series that has never been written to before then has none.
 */
export const readLatestUsageSampleBefore = async ({
    series,
    before,
}: {
    series: UsageSeries;
    before: Date;
}): Promise<UsageSample | undefined> => {
    for (const lookback of STANDING_LEVEL_LOOKBACKS_IN_MS) {
        const samples = await readUsageSamples({
            series,
            startTime: new Date(before.getTime() - lookback),
            endTime: before,
        });
        if (samples.length) {
            return samples.reduce((latest, sample) =>
                new Date(sample.timestamp).getTime() >= new Date(latest.timestamp).getTime() ? sample : latest,
            );
        }
    }
    return undefined;
};
